#nullable disable
using System;
using System.Collections.Generic;

namespace Orbit.Settings;

// Native SPT 4.1 spawn sectors and scene door interaction points. These are possible sites, not live spawns.
public static class RushDefaults
{
    public static bool IsResident(string map, string boss)
    {
        if (string.Equals(map, "Lighthouse@rework", StringComparison.OrdinalIgnoreCase))
            return boss == "bossZryachiy" || boss == "bossGluhar";
        if (string.Equals(map, "Interchange@rework", StringComparison.OrdinalIgnoreCase))
            return boss == "bossKilla" || boss == "bossTagilla";
        var key = map.Split('@')[0].ToLowerInvariant();
        return key switch
        {
            "bigmap" => boss == "bossBully",
            "factory4_day" => boss == "bossTagilla",
            "factory4_night" => boss == "bossTagilla",
            "interchange" => boss == "bossKilla",
            "rezervbase" => boss == "bossGluhar",
            "shoreline" => boss == "bossSanitar",
            "woods" => boss == "bossKojaniy",
            "tarkovstreets" => boss == "bossBoar" || boss == "bossKolontay",
            "sandbox_high" => boss == "bossKolontay",
            "lighthouse" => boss == "bossZryachiy",
            "labyrinth" => boss == "bossKillaAgro" || boss == "bossTagillaAgro",
            _ => false
        };
    }
